package com.statedriven.agent;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import java.util.*; import java.util.function.Function; import org.springframework.stereotype.Component; import reactor.core.publisher.Mono;
@Component final class AgentEngine {
 private final ObjectMapper json;private final ModelClient llm;private final FixtureTools tools; AgentEngine(ObjectMapper json,ModelClient llm,FixtureTools tools){this.json=json;this.llm=llm;this.tools=tools;}
 Mono<ObjectNode> run(ObjectNode s,ObjectNode c,int requested,Function<ObjectNode,Mono<Void>> emit){int allowance=requested>0?requested:c.at("/memory/max_steps").asInt();int limit=s.path("step_count").asInt()+allowance;s.put("run_count",s.path("run_count").asInt()+1);return emit.apply(event("status","message","Agent run started.","run_count",s.path("run_count").asInt())).then(loop(s,c,limit,allowance,emit));}
 private Mono<ObjectNode> loop(ObjectNode s,ObjectNode c,int limit,int allowance,Function<ObjectNode,Mono<Void>> emit){return Mono.defer(()->{if(!"active".equals(s.path("status").asText()))return Mono.just(s);if(s.path("step_count").asInt()>=limit){String m="Step limit ("+allowance+") reached without a final answer. Resume with another run request.";s.put("status","failed");s.put("final_answer",m);return emit.apply(event("error","message",m,"recoverable",true)).thenReturn(s);}ObjectNode transition=advance(s,c);Mono<Void> pre=transition==null?Mono.empty():emit.apply(transition);return pre.then(compact(s,c,emit)).then(emit.apply(event("status","message","Agent deciding next action.","step_count",s.path("step_count").asInt()))).then(llm.decide(c,payload(s,c))).flatMap(d->{s.put("step_count",s.path("step_count").asInt()+1);if("final".equals(d.path("type").asText())){String text=d.path("content").asText();message(s,"assistant",text,null,(String)null);if(!c.has("workflow")||s.at("/workflow/active_phase").isNull()){s.put("status","complete");s.put("final_answer",text);return emit.apply(event("final_result","answer",text)).thenReturn(s);}return loop(s,c,limit,allowance,emit);}String name=d.path("name").asText(),id=d.path("id").asText();ObjectNode call=json.createObjectNode();call.put("id",id);call.put("type","function");call.putObject("function").put("name",name).put("arguments",d.path("arguments").toString());message(s,"assistant",null,null,call);Mono<String> tool=allowed(s,c,name)?tools.execute(name,d.path("arguments")):Mono.just("ERROR: Workflow phase '"+s.at("/workflow/active_phase").asText()+"' cannot execute tool '"+name+"'. Complete the active phase first. Allowed tools: "+String.join(", ",allowedNames(s,c))+".");return tool.flatMap(output->{message(s,"tool",output,name,id);record(s,c,name,d.path("arguments"),output);return emit.apply(event("interim_result","step","tool_completed","data",Map.of("tool",name,"output",output))).then(loop(s,c,limit,allowance,emit));});});});}
 private Mono<Void> compact(ObjectNode s,ObjectNode c,Function<ObjectNode,Mono<Void>> emit){int tokens=0;for(JsonNode m:s.path("memory")){String content=m.path("content").asText();tokens+=content.codePointCount(0,content.length())/4+1;}int keep=c.at("/memory/raw_turns_to_keep").asInt(3);boolean due=tokens>=c.at("/memory/max_tokens").asInt()||s.path("step_count").asInt()>=c.at("/memory/max_steps").asInt();if(!due||s.path("memory").size()<=keep+1)return Mono.empty();ArrayNode h=json.createArrayNode(),mem=(ArrayNode)s.path("memory");for(int i=1;i<mem.size()-keep;i++)h.add(mem.get(i));return llm.compact(c,s.path("goal").asText(),h,s.path("compacted_context").asText(null),c.at("/memory/hybrid_reflection").asBoolean(true)).flatMap(x->{s.put("compacted_context",x);s.withArray("compaction_events").add(x);ArrayNode next=json.createArrayNode();next.add(mem.get(0));for(int i=Math.max(1,mem.size()-keep);i<mem.size();i++)next.add(mem.get(i));s.set("memory",next);return emit.apply(event("interim_result","step","compaction","data",Map.of("compaction_count",s.path("compaction_events").size())));});}
 private ArrayNode payload(ObjectNode s,ObjectNode c){ArrayNode a=json.createArrayNode();message(a,"system",c.path("system_prompt").asText(),null,(ObjectNode)null);message(a,"user","Original user goal (immutable): "+s.path("goal").asText(),null,(ObjectNode)null);if(s.has("compacted_context"))message(a,"system","[COMPACTED CONTEXT STATE]\n"+s.path("compacted_context").asText(),null,(ObjectNode)null);if(c.has("workflow")){JsonNode active=s.at("/workflow/active_phase");if(active.isNull())message(a,"system","[WORKFLOW STATE]\nAll configured phases have verified completion evidence. You may now provide the final answer.",null,(ObjectNode)null);else {JsonNode p=phase(c,active.asText());message(a,"system","[WORKFLOW STATE]\nActive phase: "+p.path("name").asText()+" ("+p.path("id").asText()+").\nPhase instruction: "+p.path("instruction").asText()+"\nDo not provide prose progress updates or a final answer while this phase is incomplete; make a tool call instead.\nOutstanding required evidence:\n"+String.join("\n",missing(s,p).stream().map(x->"- "+x).toList()),null,(ObjectNode)null);}}if(s.path("memory").size()>1)message(a,"system","[RAW WORKING BUFFER — PRESERVE VERBATIM]",null,(ObjectNode)null);for(int i=1;i<s.path("memory").size();i++)a.add(s.path("memory").get(i));return a;}
 private ObjectNode advance(ObjectNode s,ObjectNode c){if(!c.has("workflow"))return null;JsonNode active=s.at("/workflow/active_phase");if(active.isNull())return null;JsonNode p=phase(c,active.asText());int i=0;for(JsonNode t:p.path("transitions")){boolean applies="always".equals(t.path("when").asText())||("phase_complete".equals(t.path("when").asText("phase_complete"))&&missing(s,p).isEmpty())||("evidence".equals(t.path("when").asText())&&transitionEvidenceSeen(s,p,t,i));if(applies){String to=t.path("to").asText();if(!seenCompleted(s,p.path("id").asText()))s.with("workflow").withArray("completed_phases").add(p.path("id").asText());if("complete".equals(to))s.with("workflow").putNull("active_phase");else s.with("workflow").put("active_phase",to);ObjectNode tr=s.with("workflow").withArray("transitions").addObject();tr.put("from_phase",p.path("id").asText());tr.put("to_phase",to);tr.put("reason",t.path("when").asText("phase_complete"));return event("interim_result","step","phase_completed","phase_id",p.path("id").asText(),"next_phase",to,"reason",t.path("when").asText("phase_complete"));}i++;}return null;}
 private List<String> missing(ObjectNode s,JsonNode p){List<String>x=new ArrayList<>();int i=0;for(JsonNode e:p.path("completion")){if(e.path("required").asBoolean(true)&&!seen(s,p.path("id").asText()+":completion:"+i))x.add(e.path("description").asText());i++;}return x;}
 private void record(ObjectNode s,ObjectNode c,String name,JsonNode args,String out){if(!c.has("workflow")||s.at("/workflow/active_phase").isNull())return;JsonNode p=phase(c,s.at("/workflow/active_phase").asText());int i=0;for(JsonNode e:p.path("completion")){String key=p.path("id").asText()+":completion:"+i++;if(!seen(s,key)&&matches(e,name,args,out))s.with("workflow").withArray("observed_evidence").add(key);}i=0;for(JsonNode t:p.path("transitions")){int j=0;for(JsonNode e:t.path("evidence")){String key=p.path("id").asText()+":transition-"+i+":"+j++;if(!seen(s,key)&&matches(e,name,args,out))s.with("workflow").withArray("observed_evidence").add(key);}i++;}}
 private boolean matches(JsonNode e,String n,JsonNode a,String out){if(!n.equals(e.path("tool").asText())||!contains(a,e.path("arguments")))return false;for(JsonNode term:e.path("content_contains"))if(!out.toLowerCase().contains(term.asText().toLowerCase()))return false;if(!e.has("result")||e.path("result").isEmpty())return true;try{return contains(json.readTree(out),e.path("result"));}catch(Exception x){return false;}}
 private boolean contains(JsonNode a,JsonNode e){if(e==null||e.isMissingNode()||e.isEmpty())return true;if(e.isObject()){if(!a.isObject())return false;var it=e.fields();while(it.hasNext()){var x=it.next();if(!a.has(x.getKey())||!contains(a.get(x.getKey()),x.getValue()))return false;}return true;}if(e.isArray()){for(JsonNode x:e){boolean found=false;for(JsonNode y:a)if(y.equals(x)){found=true;break;}if(!found)return false;}return true;}return a.equals(e);}
 private boolean transitionEvidenceSeen(ObjectNode s,JsonNode p,JsonNode t,int transitionIndex){int i=0;for(JsonNode ignored:t.path("evidence")){if(!seen(s,p.path("id").asText()+":transition-"+transitionIndex+":"+i++))return false;}return true;} private boolean seenCompleted(ObjectNode s,String phase){for(JsonNode x:s.at("/workflow/completed_phases"))if(phase.equals(x.asText()))return true;return false;} private boolean seen(ObjectNode s,String key){for(JsonNode x:s.at("/workflow/observed_evidence"))if(key.equals(x.asText()))return true;return false;} private JsonNode phase(ObjectNode c,String id){for(JsonNode p:c.at("/workflow/phases"))if(id.equals(p.path("id").asText()))return p;throw new IllegalArgumentException("unknown workflow phase "+id);} private boolean allowed(ObjectNode s,ObjectNode c,String tool){if(!c.has("workflow")||s.at("/workflow/active_phase").isNull())return true;for(String n:allowedNames(s,c))if(n.equals(tool))return true;return false;} private List<String> allowedNames(ObjectNode s,ObjectNode c){JsonNode p=phase(c,s.at("/workflow/active_phase").asText());List<String> names=new ArrayList<>();JsonNode permitted=p.path("allowed_tools");if(permitted.isArray())for(JsonNode n:permitted)names.add(n.asText());else for(JsonNode e:p.path("completion"))names.add(e.path("tool").asText());return names;} private void message(ArrayNode a,String role,String content,String name,ObjectNode call){ObjectNode m=a.addObject();m.put("role",role);if(content!=null)m.put("content",content);if(name!=null)m.put("name",name);if(call!=null)m.putArray("tool_calls").add(call);} private void message(ObjectNode s,String role,String content,String name,String id){ObjectNode m=s.withArray("memory").addObject();m.put("role",role);if(content!=null)m.put("content",content);if(name!=null)m.put("name",name);if(id!=null)m.put("tool_call_id",id);} private void message(ObjectNode s,String role,String content,String name,ObjectNode call){message(s.withArray("memory"),role,content,name,call);} private ObjectNode event(String type,Object...kv){ObjectNode e=json.createObjectNode();e.put("type",type);for(int i=0;i<kv.length;i+=2)e.set(kv[i].toString(),json.valueToTree(kv[i+1]));return e;}
}
